import express from 'express';
import { SQL } from 'bun';
import { verifyPlayerJwt } from '../auth.js';

const app = express();
app.use(express.json());
const sql = new SQL(process.env.GAME_DB_URL);

app.post('/api/gaming/inventory/:itemId/transfer', verifyPlayerJwt, async (req, res) => {
  const { itemId } = req.params;
  const { recipientPlayerId } = req.body;

  // Enforce that the item being transferred currently belongs to the authenticated player
  const result = await sql`
    UPDATE player_inventory
    SET player_id = ${recipientPlayerId}, updated_at = NOW()
    WHERE id = ${itemId} AND player_id = ${req.player.id}
    RETURNING id, item_type, rarity, player_id
  `;

  if (result.length === 0) {
    return res.status(404).json({ error: 'Item not found or you do not own this item' });
  }

  res.json({ success: true, transferredItem: result[0] });
});

export default app;
